<?php
require __DIR__.'/base.php';$id=autenticado();$db=banco();$stmt=$db->prepare("SELECT s.id_solicitacao,i.nome AS produto,CASE WHEN i.id_usuario_publicador=? THEN s.id_usuario_solicitante ELSE i.id_usuario_publicador END AS avaliado,u.nome AS pessoa FROM solicitacao s JOIN solicitacao_item si ON si.id_solicitacao=s.id_solicitacao JOIN item i ON i.id_item=si.id_item JOIN usuario u ON u.id_usuario=CASE WHEN i.id_usuario_publicador=? THEN s.id_usuario_solicitante ELSE i.id_usuario_publicador END LEFT JOIN avaliacao a ON a.id_solicitacao=s.id_solicitacao AND a.id_usuario_avaliador=? WHERE s.status_soli='Concluída' AND (s.id_usuario_solicitante=? OR i.id_usuario_publicador=?) AND a.id_avaliacao IS NULL ORDER BY s.id_solicitacao DESC");$stmt->bind_param('iiiii',$id,$id,$id,$id,$id);$stmt->execute();$rows=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();responder('ok','Avaliações disponíveis.',$rows);
